//...................Discriminated Unions & The never Type.................

type StripePayment = { kind: "stripe"; amount: number };

type GithubPush = { kind: "github"; commitSha: string };

type AutonomousAgentLog = { kind: "agent"; message: string };

type WebhookPayload = StripePayment | GithubPush | AutonomousAgentLog;

function processWebhook(payload: WebhookPayload) {
    switch (payload.kind) {
        case "stripe":
            console.log("Processing payment:", payload.amount);
            break;
        case "github":
            console.log("Deploying commit:", payload.commitSha);
            break;
        case "agent":
            console.log("Logging agent activity:", payload.message);
            break;
        default:
            const _exhaustiveCheck: never = payload;

            throw new Error(`Unhandled webhook kind: ${JSON.stringify(_exhaustiveCheck)}`);
    }
}